/bin/zsh -lc "./run_python - <<'PY'
import app

# UTF-8 codepoint split across transport chunks, and whole frame split arbitrarily.
p = app.EventStream()
wire = '{\"event\":\"token\",\"text\":\"雪🙂\"}\\n{\"event\":\"done\"}\\n'.encode()
events = []
for byte in wire:
    events.extend(p.feed(bytes([byte])))
assert events == [
    {\"event\": \"token\", \"text\": \"雪🙂\"},
    {\"event\": \"done\", \"text\": \"雪🙂\", \"characters\": 2, \"words\": 1},
]
assert p.buffered_bytes == 0 and p.finish() == [] and p.finish() == []

# Many frames in a chunk may exceed the per-frame limit in total.
p = app.EventStream(max_buffer=16)
data = b'{\"event\":\"token\",\"text\":\"\"}\\n' * 20 + b'{\"event\":\"done\"}\\n'
assert len(p.feed(data)) == 21

# Exact byte limit is accepted; one byte over fails and clears state.
frame = b'{\"event\":\"done\"}'
p = app.EventStream(max_buffer=len(frame))
assert p.feed(frame + b'\\n')[0][\"event\"] == \"done\"
p = app.EventStream(max_buffer=len(frame) - 1)
try:
    p.feed(frame + b'\\n')
except app.StreamError:
    assert p.state == \"FAILED\" and p.buffered_bytes == 0
else:
    raise AssertionError(\"oversized frame accepted\")

# Trailing bytes after a terminal event in the same call fail the whole feed.
for suffix in (b'x', b'\\n', b'{\"event\":\"done\"}\\n'):
    p = app.EventStream()
    try:
        p.feed(b'{\"event\":\"done\"}\\n' + suffix)
    except app.StreamError:
        assert p.state == \"FAILED\" and p.buffered_bytes == 0
    else:
        raise AssertionError(\"trailing post-terminal data accepted\")

# Malformed frame, empty frame, premature EOF, and post-failure calls.
for data in (b'\\n', b'{}\\n', b'\\xff\\n'):
    p = app.EventStream()
    try:
        p.feed(data)
    except app.StreamError:
        assert p.state == \"FAILED\" and p.buffered_bytes == 0
    else:
        raise AssertionError(\"invalid frame accepted\")
    for call in (lambda: p.feed(b''), p.finish):
        try:
            call()
        except app.StreamError:
            pass
        else:
            raise AssertionError(\"failed stream reused\")
p = app.EventStream()
assert p.feed(b'{\"event\":') == [] and p.buffered_bytes == 9
try:
    p.finish()
except app.StreamError:
    assert p.state == \"FAILED\" and p.buffered_bytes == 0
else:
    raise AssertionError(\"premature EOF accepted\")

# Error termination and Unicode whitespace metrics.
p = app.EventStream()
assert p.feed(b'{\"event\":\"token\",\"text\":\"a\\\\u2003b\"}\\n{\"event\":\"error\",\"message\":\"stop\"}\\n') == [
    {\"event\": \"token\", \"text\": \"a\\u2003b\"},
    {\"event\": \"error\", \"message\": \"stop\"},
]
assert app.text_metrics(\"a\\u2003b\") == {\"characters\": 3, \"words\": 2}
assert p.finish() == []
print(\"targeted checks passed\")
PY"

